css:
/* Мягкий параллакс: фон и иллюстрация чуть отстают от прокрутки.
   Сдвиг задаётся в px через --px-shift: слой проходит путь от -сдвига до +сдвига,
   пока секция пересекает экран. Полный ход = 2 x сдвиг, держим его меньше 100 px. */
.px-scene {
  position: relative;
  isolation: isolate;               /* фон с z-index:-1 остаётся внутри секции */
  overflow: hidden;
  overflow: clip;                   /* обрезает края слоёв и не создаёт контейнер прокрутки */
  view-timeline-name: --px-scene;   /* шкала «секция проходит через экран» для слоёв внутри */
  /* вертикальный отступ секции (из дизайн-системы) должен быть больше сдвига ближнего слоя,
     иначе край картинки обрежется */
}
.px-layer { --px-shift: 40px; pointer-events: none; }
.px-layer--deep { --px-shift: 20px; }   /* дальний слой движется в два раза меньше */
.px-layer--bg {
  position: absolute;
  z-index: -1;
  inset: calc(var(--px-shift) * -1) 0; /* запас сверху и снизу на величину сдвига: край не откроется */
  background:
    radial-gradient(55% 45% at 18% 30%, color-mix(in srgb, var(--accent, #6d5efc) 16%, transparent), transparent 70%),
    radial-gradient(45% 40% at 85% 75%, color-mix(in srgb, var(--primary, #0e7c66) 14%, transparent), transparent 70%);
}
.px-grid { display: grid; grid-template-columns: 1fr; gap: 32px; align-items: center; }
.px-art img { display: block; width: 100%; height: auto; }
@media (min-width: 768px) {
  .px-grid { grid-template-columns: 1.1fr 1fr; gap: 64px; }
}
@media (max-width: 767px) {            /* на телефоне ход вдвое меньше */
  .px-layer { --px-shift: 20px; }
  .px-layer--deep { --px-shift: 10px; }
}
@keyframes px-drift {
  from { transform: translate3d(0, calc(var(--px-shift) * -1), 0); }
  to { transform: translate3d(0, var(--px-shift), 0); }
}
@media (prefers-reduced-motion: no-preference) {
  .px-layer { will-change: transform; }
  /* Современные браузеры двигают слой сами, без JS и в отдельном потоке */
  @supports (animation-timeline: view()) {
    .px-layer {
      animation: px-drift 1ms linear both; /* 1ms нужен Firefox: без длительности он не применяет анимацию; на шкале прокрутки время пересчитывается в долю пути */
      animation-timeline: --px-scene;  /* строго ПОСЛЕ animation: сокращённая запись сбрасывает шкалу */
    }
    /* JS ставит .px-js, если шкала замерла (секцию держит непрокручиваемый контейнер) — тогда слой двигает он */
    .px-scene.px-js .px-layer { animation: none; }
  }
}
/* Уровень 1 по схеме iart: параллакс убираем целиком, слои стоят на месте, композиция та же */
@media (prefers-reduced-motion: reduce) {
  .px-layer { animation: none !important; transform: none !important; will-change: auto; }
}

js:
// Запасной путь на JS: двигает слои там, где CSS-шкала прокрутки не работает.
(() => {
  const all = [...document.querySelectorAll('.px-scene')];
  if (!all.length) return;
  const cssOk = !!(window.CSS && CSS.supports('animation-timeline', 'view()'));
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  const scenes = []; let raf = 0;
  // CSS-шкала «замерла»: секцию держит непрокручиваемый контейнер (частый случай — html, body { overflow-x: hidden })
  const frozen = s => {
    const src = s.querySelector('.px-layer')?.getAnimations()[0]?.timeline?.source;
    return !!src && src !== document.scrollingElement && src.scrollHeight <= src.clientHeight;
  };
  const pick = () => all.forEach(s => {
    if (s.classList.contains('px-js') || (cssOk && !frozen(s))) return;
    s.classList.add('px-js'); scenes.push(s); // .px-js снимает CSS-анимацию — слоем управляет JS
  });
  const frame = () => {
    raf = 0;
    if (reduce.matches || !scenes.length) return;
    const vh = innerHeight;
    // сначала все чтения, потом все записи — без лишних пересчётов раскладки
    const plan = scenes.flatMap(scene => {
      const r = scene.getBoundingClientRect();
      if (r.bottom < -200 || r.top > vh + 200) return []; // далеко за экраном — не трогаем
      // 0 — верх секции у низа экрана, 1 — низ секции у верха экрана (как шкала view() в CSS)
      const p = Math.min(1, Math.max(0, (vh - r.top) / (vh + r.height)));
      return [...scene.querySelectorAll('.px-layer')].map(l =>
        [l, (2 * p - 1) * (parseFloat(getComputedStyle(l).getPropertyValue('--px-shift')) || 0)]);
    });
    for (const [l, y] of plan) l.style.transform = `translate3d(0, ${y.toFixed(1)}px, 0)`;
  };
  const tick = () => { if (!raf) raf = requestAnimationFrame(frame); };
  addEventListener('scroll', tick, { passive: true, capture: true }); // capture — и прокрутка внутри контейнеров
  addEventListener('resize', tick);
  reduce.addEventListener('change', () => { // настройку меняют и на открытой странице
    if (reduce.matches) scenes.forEach(s => s.querySelectorAll('.px-layer').forEach(l => { l.style.transform = ''; }));
    else { pick(); tick(); } // при reduce на загрузке CSS-анимации не было — проверяем шкалу сейчас
  });
  pick(); tick();
})();

gsap_alt:
Если на странице уже есть GSAP из npm (npm i gsap), удалите из CSS блок @supports с animation-timeline (вместе с правилом .px-js) и ванильный JS — иначе слой получит два сдвига (CSS-анимация перекрывает inline-стиль GSAP). Затем:
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
const shift = l => parseFloat(getComputedStyle(l).getPropertyValue('--px-shift')) || 0;
gsap.matchMedia().add('(prefers-reduced-motion: no-preference)', () => {
  gsap.utils.toArray('.px-scene').forEach(scene => {
    scene.querySelectorAll('.px-layer').forEach(l => {
      gsap.fromTo(l, { y: () => -shift(l) }, { y: () => shift(l), ease: 'none',
        scrollTrigger: { trigger: scene, start: 'top bottom', end: 'bottom top', scrub: true, invalidateOnRefresh: true } });
    });
  });
});
// matchMedia сам откатывает сдвиги, когда человек включает «уменьшить движение».
